sp_widget.client_script:
api.controller=function($scope, $window, $timeout) {
  var c = this;

  c.showForm = true;
  c.submitted = false;
  c.submitting = false;
  c.request = {
    is_half_day: false,
    half_day_period: 'morning'
  };
  c.leaveTypes = [];
  c.message = '';
  c.messageType = 'info';

  c.$onInit = function() {
    c.server.get().then(function() {
      // Initialize with default values
      if (c.data.currentUser) {
        c.request.requested_by = c.data.currentUser.sys_id;
      }

      c.leaveTypes = c.data.leaveTypes || [];
    });
  };

  c.updateDuration = function() {
    if (c.request.start_date && c.request.end_date) {
      c.server.get({
        action: 'calculateDuration',
        start_date: c.request.start_date,
        end_date: c.request.end_date,
        is_half_day: c.request.is_half_day
      }).then(function(response) {
        c.request.duration = c.data.duration;

        if (c.data.message) {
          c.message = c.data.message;
          c.messageType = c.data.messageType || 'info';
        } else {
          c.message = '';
        }
      });
    }
  };

  c.halfDayChanged = function() {
    if (c.request.is_half_day) {
      // For half day, end date is same as start date
      c.request.end_date = c.request.start_date;
    }
    c.updateDuration();
  };

  c.submitForm = function() {
    c.submitting = true;
    c.message = '';

    c.server.get({
      action: 'submitRequest',
      request: c.request
    }).then(function(response) {
      c.submitting = false;

      if (c.data.error) {
        c.message = c.data.error;
        c.messageType = 'danger';
      } else {
        c.showForm = false;
        c.submitted = true;
        c.requestNumber = c.data.requestNumber;
      }
    });
  };

  c.cancel = function() {
    c.goToDashboard();
  };

  c.goToDashboard = function() {
    $window.location.href = '?id=lms_app';
  };

  c.newRequest = function() {
    c.request = {
      is_half_day: false,
      half_day_period: 'morning'
    };
    c.message = '';
    c.showForm = true;
    c.submitted = false;
  };
};

sp_widget.script:
(function() {
  // Get current user
  data.currentUser = {
    sys_id: gs.getUserID(),
    name: gs.getUserName()
  };

  // Get leave types
  data.leaveTypes = [];
  var leaveTypeGR = new GlideRecord('x_1800027_leve_sys_leave_type');
  leaveTypeGR.query();
  while (leaveTypeGR.next()) {
    data.leaveTypes.push({
      sys_id: leaveTypeGR.getUniqueValue(),
      name: leaveTypeGR.name.toString()
    });
  }

  // Handle actions
  if (input && input.action) {
    switch(input.action) {
      case 'calculateDuration':
        calculateDuration();
        break;
      case 'submitRequest':
        submitRequest();
        break;
    }
  }

  // Calculate duration between dates
  function calculateDuration() {
    if (!input.start_date || !input.end_date) {
      data.duration = 0;
      return;
    }

    try {
      // Use your existing HolidayManager to calculate working days
      var holidayManager = new x_1800027_leve_sys.HolidayManager();
      var startDate = new GlideDateTime(input.start_date);
      var endDate = new GlideDateTime(input.end_date);

      // For half day, duration is 0.5
      if (input.is_half_day === true || input.is_half_day === 'true') {
        data.duration = 0.5;
      } else {
        // Calculate working days
        data.duration = holidayManager.getWorkingDaysBetweenDates(startDate, endDate);
      }

      // Check leave balance
      checkLeaveBalance();
    } catch (e) {
      gs.log('Error calculating duration: ' + e);
      data.duration = 0;
      data.message = 'Error calculating duration. Please try again.';
      data.messageType = 'danger';
    }
  }

  // Check leave balance
  function checkLeaveBalance() {
    if (!input.start_date || !input.end_date || !data.currentUser.sys_id) {
      return;
    }

    try {
      var balanceGR = new GlideRecord('x_1800027_leve_sys_leave_balance');
      balanceGR.addQuery('employee', data.currentUser.sys_id);
      if (input.leave_type) {
        balanceGR.addQuery('leave_type', input.leave_type);
      }
      balanceGR.query();

      if (balanceGR.next()) {
        var availableBalance = parseFloat(balanceGR.available_balance.toString());

        if (data.duration > availableBalance) {
          data.message = 'Warning: The requested leave duration exceeds your available balance of ' + availableBalance + ' days.';
          data.messageType = 'warning';
        } else {
          data.message = 'You have ' + availableBalance + ' days available.';
          data.messageType = 'info';
        }
      }
    } catch (e) {
      gs.log('Error checking leave balance: ' + e);
    }
  }

  // Submit leave request
  function submitRequest() {
    if (!input.request) {
      data.error = 'Invalid request data';
      return;
    }

    try {
      var leaveGR = new GlideRecord('x_1800027_leve_sys_leave_request');
      leaveGR.initialize();

      // Set fields from input
      leaveGR.requested_by = data.currentUser.sys_id;
      leaveGR.leave_type = input.request.leave_type;
      leaveGR.start_date = input.request.start_date;
      leaveGR.end_date = input.request.end_date;
      leaveGR.is_half_day = input.request.is_half_day === true || input.request.is_half_day === 'true';

      if (leaveGR.is_half_day) {
        leaveGR.half_day_period = input.request.half_day_period;
      }

      leaveGR.comments = input.request.comments;
      leaveGR.duration = input.request.duration;
      leaveGR.status = 'requested'; // Initial status

      // Insert record
      var result = leaveGR.insert();

      if (result) {
        data.requestNumber = leaveGR.number.toString();
      } else {
        data.error = 'Failed to submit leave request. Please try again.';
      }
    } catch (e) {
      gs.log('Error submitting leave request: ' + e);
      data.error = 'Error: ' + e.message;
    }
  }
})();
